1	package com.example.starter.service;
2	
3	import com.example.starter.domain.JobStatus;
4	import com.example.starter.domain.TestResult;
5	import com.example.starter.domain.TestType;
6	import com.example.starter.repo.BrakeTestRepository;
7	import com.example.starter.repo.BrakeTestRow;
8	import com.example.starter.repo.ConsistCheckRepository;
9	import com.example.starter.repo.JobRow;
10	import com.example.starter.repo.PressureReadingRepository;
11	import com.example.starter.repo.CarRow;
12	import com.example.starter.repo.TrainCarRepository;
13	import com.example.starter.repo.TrainJobRepository;
14	import com.example.starter.web.dto.AcceptJobRequest;
15	import com.example.starter.web.dto.BrakeTestRequest;
16	import com.example.starter.web.dto.BrakeTestResponse;
17	import com.example.starter.web.dto.CarDto;
18	import com.example.starter.web.dto.ClosedCarListResponse;
19	import com.example.starter.web.dto.ClosureResponse;
20	import com.example.starter.web.dto.ConsistChangeRequest;
21	import com.example.starter.web.dto.ConsistChangeResponse;
22	import com.example.starter.web.dto.ConsistCheckRequest;
23	import com.example.starter.web.dto.ConsistCheckResponse;
24	import com.example.starter.web.dto.ConsistResponse;
25	import com.example.starter.web.dto.DepartureResponse;
26	import com.example.starter.web.dto.JobResponse;
27	import com.example.starter.web.dto.PressureReadingRequest;
28	import com.example.starter.web.dto.PressureReadingResponse;
29	import com.example.starter.web.dto.RequestIdOnly;
30	import com.example.starter.web.dto.TestCurveResponse;
31	import org.springframework.dao.DuplicateKeyException;
32	import org.springframework.stereotype.Service;
33	import org.springframework.transaction.annotation.Transactional;
34	
35	import java.math.BigDecimal;
36	import java.util.List;
37	
38	/**
39	 * 列车制动机试验与摘挂核对核心服务。
40	 * 流程：接入 → 摘挂 → 编组核对 → 制动试验（感度/安定） → 发车确认 → 销记终态。
41	 */
42	@Service
43	public class TrainJobService {
44	
45	    /** 列车管定压，单位 kPa；两项试验之间须恢复至定压，恰达定压允许下一项。 */
46	    public static final int RATED_PRESSURE_KPA = 500;
47	    /** 感度试验减压量，单位 kPa。 */
48	    public static final int SENSITIVITY_REDUCTION_KPA = 50;
49	    /** 安定试验减压量，单位 kPa；恰 140kPa 合格。 */
50	    public static final int STABILITY_REDUCTION_KPA = 140;
51	    /** 关门车比例上限分子（6%），恰 6% 合法。 */
52	    public static final int CLOSED_CAR_LIMIT_PERCENT = 6;
53	
54	    private final TrainJobRepository jobRepository;
55	    private final TrainCarRepository carRepository;
56	    private final BrakeTestRepository brakeTestRepository;
57	    private final ConsistCheckRepository consistCheckRepository;
58	    private final PressureReadingRepository pressureReadingRepository;
59	    private final IdempotencyService idempotencyService;
60	    private final EotService eotService;
61	
62	    public TrainJobService(TrainJobRepository jobRepository, TrainCarRepository carRepository,
63	                           BrakeTestRepository brakeTestRepository,
64	                           ConsistCheckRepository consistCheckRepository,
65	                           PressureReadingRepository pressureReadingRepository,
66	                           IdempotencyService idempotencyService,
67	                           EotService eotService) {
68	        this.jobRepository = jobRepository;
69	        this.carRepository = carRepository;
70	        this.brakeTestRepository = brakeTestRepository;
71	        this.consistCheckRepository = consistCheckRepository;
72	        this.pressureReadingRepository = pressureReadingRepository;
73	        this.idempotencyService = idempotencyService;
74	        this.eotService = eotService;
75	    }
76	
77	    /**
78	     * 接入列车作业；同一股道同时刻仅允许一列作业中列车，并发接入唯一受理。
79	     */
80	    public JobResponse accept(AcceptJobRequest request) {
81	        return idempotencyService.execute(request.requestId(), "ACCEPT", request,
82	                JobResponse.class, () -> doAccept(request));
83	    }
84	
85	    /**
86	     * 摘挂变更；变更与试验结论作废在同一事务内完成，变更后须重新核对与重做试验。
87	     */
88	    public ConsistChangeResponse changeConsist(long jobId, ConsistChangeRequest request) {
89	        return idempotencyService.execute(request.requestId(), "CONSIST_CHANGE", request,
90	                ConsistChangeResponse.class, () -> doChangeConsist(jobId, request));
91	    }
92	
93	    /**
94	     * 编组核对：辆数、换长、总重与合成运统1比对，不一致则拒绝后续发车。
95	     */
96	    public ConsistCheckResponse checkConsist(long jobId, ConsistCheckRequest request) {
97	        return idempotencyService.execute(request.requestId(), "CONSIST_CHECK", request,
98	                ConsistCheckResponse.class, () -> doCheckConsist(jobId, request));
99	    }
100	
101	    /**
102	     * 制动试验：感度减压 50kPa 全列须制动；安定减压 140kPa 不得紧急制动；
103	     * 两项之间风压须恢复至定压 500kPa（恰达允许）。
104	     */
105	    public BrakeTestResponse brakeTest(long jobId, BrakeTestRequest request) {
106	        return idempotencyService.execute(request.requestId(), "BRAKE_TEST", request,
107	                BrakeTestResponse.class, () -> doBrakeTest(jobId, request));
108	    }
109	
110	    /**
111	     * 发车确认：运统1核对一致、感度与安定均合格、关门车比例不超限方可发车。
112	     */
113	    public DepartureResponse confirmDeparture(long jobId, RequestIdOnly request) {
114	        return idempotencyService.execute(request.requestId(), "DEPARTURE", request,
115	                DepartureResponse.class, () -> doConfirmDeparture(jobId));
116	    }
117	
118	    /**
119	     * 销记：终态；重复销记返回幂等成功。
120	     */
121	    public ClosureResponse close(long jobId, RequestIdOnly request) {
122	        return idempotencyService.execute(request.requestId(), "CLOSURE", request,
123	                ClosureResponse.class, () -> doClose(jobId));
124	    }
125	
126	    /**
127	     * 风压读数上报；销记后迟到数据只记迟到事件。
128	     */
129	    public PressureReadingResponse reportPressure(long jobId, PressureReadingRequest request) {
130	        return idempotencyService.execute(request.requestId(), "PRESSURE", request,
131	                PressureReadingResponse.class, () -> doReportPressure(jobId, request));
132	    }
133	
134	    private JobResponse doAccept(AcceptJobRequest request) {
135	        List<CarDto> cars = request.cars();
136	        checkClosedCarRatio(cars);
137	        BigDecimal totalLength = cars.stream().map(CarDto::length).reduce(BigDecimal.ZERO, BigDecimal::add);
138	        BigDecimal totalWeight = cars.stream().map(CarDto::weightTons).reduce(BigDecimal.ZERO, BigDecimal::add);
139	        long jobId;
140	        try {
141	            jobId = jobRepository.insert(request.trainNo(), request.track(),
142	                    cars.size(), totalLength, totalWeight);
143	        } catch (DuplicateKeyException e) {
144	            throw new ConflictException("同一股道同时刻仅允许一列作业中列车：" + request.track());
145	        }
146	        for (int i = 0; i < cars.size(); i++) {
147	            carRepository.insert(jobId, i + 1, cars.get(i));
148	        }
149	        return toJobResponse(jobRepository.findById(jobId).orElseThrow());
150	    }
151	
152	    private ConsistChangeResponse doChangeConsist(long jobId, ConsistChangeRequest request) {
153	        JobRow job = requireJobForUpdate(jobId);
154	        if (job.status() != JobStatus.ACCEPTED && job.status() != JobStatus.CHECKED) {
155	            throw new BusinessException("当前状态不允许摘挂变更：" + job.status());
156	        }
157	        for (String carNo : request.detachCarNos()) {
158	            if (!carRepository.detach(jobId, carNo)) {
159	                throw new BusinessException("摘车失败，车辆不存在或已摘下：" + carNo);
160	            }
161	        }
162	        int nextSeq = carRepository.findActiveByJobId(jobId).size();
163	        for (CarDto car : request.attachCars()) {
164	            List<CarRow> existing = carRepository.findByJobIdAndCarNo(jobId, car.carNo());
165	            if (!existing.isEmpty()) {
166	                if (existing.get(0).detached()) {
167	                    nextSeq++;
168	                    carRepository.reattach(jobId, car.carNo(), nextSeq);
169	                } else {
170	                    throw new BusinessException("挂车失败，车辆已在列：" + car.carNo());
171	                }
172	            } else {
173	                nextSeq++;
174	                carRepository.insert(jobId, nextSeq, car);
175	            }
176	        }
177	        List<CarRow> active = carRepository.findActiveByJobId(jobId);
178	        if (active.isEmpty()) {
179	            throw new BusinessException("摘挂后在列辆数不得为空");
180	        }
181	        checkClosedCarRatio(active.stream()
182	                .map(c -> new CarDto(c.carNo(), c.weightTons(), c.length(), c.valveClosed()))
183	                .toList());
184	        int voidedTests = brakeTestRepository.voidAllByJobId(jobId);
185	        BigDecimal totalLength = active.stream().map(CarRow::length).reduce(BigDecimal.ZERO, BigDecimal::add);
186	        BigDecimal totalWeight = active.stream().map(CarRow::weightTons).reduce(BigDecimal.ZERO, BigDecimal::add);
187	        int newVersion = job.consistVersion() + 1;
188	        jobRepository.updateConsist(jobId, newVersion, active.size(), totalLength, totalWeight,
189	                false, JobStatus.ACCEPTED);
190	        // 编组变化（含尾车/版本变化）：列尾绑定保留，但一致性确认立即失效，须重新双人确认
191	        eotService.invalidateConfirmationsOnConsistChange(jobId);
192	        return new ConsistChangeResponse(jobId, newVersion, active.size(), totalLength, totalWeight, voidedTests);
193	    }
194	
195	    private ConsistCheckResponse doCheckConsist(long jobId, ConsistCheckRequest request) {
196	        JobRow job = requireJobForUpdate(jobId);
197	        if (job.status() == JobStatus.DEPARTURE_CONFIRMED || job.status() == JobStatus.CLOSED) {
198	            throw new BusinessException("当前状态不允许编组核对：" + job.status());
199	        }
200	        boolean matched = request.expectedCarCount() == job.carCount()
201	                && request.expectedTotalLength().compareTo(job.totalLength()) == 0
202	                && request.expectedTotalWeight().compareTo(job.totalWeight()) == 0;
203	        long checkId = consistCheckRepository.insert(jobId, job.consistVersion(),
204	                request.expectedCarCount(), request.expectedTotalLength(), request.expectedTotalWeight(),
205	                job.carCount(), job.totalLength(), job.totalWeight(), matched, request.requestId());
206	        jobRepository.updateStatusAndChecked(jobId,
207	                matched ? JobStatus.CHECKED : JobStatus.ACCEPTED, matched);
208	        String message = matched ? "编组与运统1一致" : "编组与运统1不一致，拒绝发车";
209	        return new ConsistCheckResponse(checkId, matched, job.consistVersion(),
210	                request.expectedCarCount(), job.carCount(),
211	                request.expectedTotalLength(), job.totalLength(),
212	                request.expectedTotalWeight(), job.totalWeight(), message);
213	    }
214	
215	    private BrakeTestResponse doBrakeTest(long jobId, BrakeTestRequest request) {
216	        JobRow job = requireJobForUpdate(jobId);
217	        if (job.status() != JobStatus.CHECKED) {
218	            throw new BusinessException("编组未通过运统1核对或状态不允许试验：" + job.status());
219	        }
220	        if (request.pipePressureBefore() < RATED_PRESSURE_KPA) {
221	            throw new BusinessException("风压未恢复至定压 " + RATED_PRESSURE_KPA + "kPa，不得进行试验");
222	        }
223	        TestResult result;
224	        String message;
225	        if (request.testType() == TestType.SENSITIVITY) {
226	            if (request.pressureReduction() != SENSITIVITY_REDUCTION_KPA) {
227	                throw new BusinessException("感度试验减压量须为 " + SENSITIVITY_REDUCTION_KPA + "kPa");
228	            }
229	            if (request.allCarsBraked() == null) {
230	                throw new BusinessException("感度试验须上报全列制动情况");
231	            }
232	            result = request.allCarsBraked() ? TestResult.PASS : TestResult.FAIL;
233	            message = result == TestResult.PASS ? "感度试验合格" : "感度试验不合格：存在未制动车辆";
234	        } else {
235	            requireSensitivityPassed(job);
236	            if (request.pressureReduction() != STABILITY_REDUCTION_KPA) {
237	                throw new BusinessException("安定试验减压量须为 " + STABILITY_REDUCTION_KPA + "kPa");
238	            }
239	            if (request.emergencyOccurred() == null) {
240	                throw new BusinessException("安定试验须上报紧急制动情况");
241	            }
242	            result = request.emergencyOccurred() ? TestResult.FAIL : TestResult.PASS;
243	            message = result == TestResult.PASS ? "安定试验合格" : "安定试验不合格：发生紧急制动";
244	        }
245	        long testId = brakeTestRepository.insert(jobId, job.consistVersion(), request.testType(),
246	                request.pressureReduction(), request.pipePressureBefore(),
247	                request.allCarsBraked(), request.emergencyOccurred(), result, request.requestId());
248	        return new BrakeTestResponse(testId, request.testType().name(), result.name(),
249	                job.consistVersion(), message);
250	    }
251	
252	    private DepartureResponse doConfirmDeparture(long jobId) {
253	        JobRow job = requireJobForUpdate(jobId);
254	        if (job.status() == JobStatus.CLOSED) {
255	            throw new BusinessException("作业已销记，不得重复发车确认");
256	        }
257	        if (job.status() == JobStatus.DEPARTURE_CONFIRMED) {
258	            return new DepartureResponse(jobId, true, "已确认发车");
259	        }
260	        if (!job.consistChecked()) {
261	            throw new BusinessException("编组与运统1不一致或未核对，拒绝发车");
262	        }
263	        requirePassed(job, TestType.SENSITIVITY);
264	        requirePassed(job, TestType.STABILITY);
265	        List<CarRow> active = carRepository.findActiveByJobId(jobId);
266	        long closed = active.stream().filter(CarRow::valveClosed).count();
267	        if (!withinClosedCarLimit(closed, active.size())) {
268	            throw new BusinessException("关门车比例超过 6%，拒绝发车");
269	        }
270	        // 原制动试验仍有效的前提下，事务内同时核对列尾装置自检未过期、双人一致性确认匹配最新编组；
271	        // 未绑定列尾装置的历史作业不增加新门禁
272	        eotService.assertDepartureReady(job);
273	        jobRepository.updateStatus(jobId, JobStatus.DEPARTURE_CONFIRMED);
274	        return new DepartureResponse(jobId, true, "准许发车");
275	    }
276	
277	    private ClosureResponse doClose(long jobId) {
278	        JobRow job = requireJobForUpdate(jobId);
279	        if (job.status() == JobStatus.CLOSED) {
280	            return new ClosureResponse(jobId, true, true, "重复销记，幂等成功");
281	        }
282	        if (job.status() != JobStatus.DEPARTURE_CONFIRMED) {
283	            throw new BusinessException("未发车确认，不得销记：" + job.status());
284	        }
285	        jobRepository.close(jobId);
286	        // 销记原子解除列尾装置占用、解除绑定并失效确认，绑定历史保留
287	        eotService.releaseOnClosure(jobId);
288	        return new ClosureResponse(jobId, true, false, "销记完成，作业终态");
289	    }
290	
291	    private PressureReadingResponse doReportPressure(long jobId, PressureReadingRequest request) {
292	        JobRow job = requireJob(jobId);
293	        if (job.status() == JobStatus.CLOSED) {
294	            pressureReadingRepository.insertLateEvent(jobId, "LATE_PRESSURE",
295	                    "销记后迟到风压数据：" + request.pressure() + "kPa，采集时间 " + request.recordedAt());
296	            return new PressureReadingResponse(null, false, true, "作业已销记，迟到数据仅记迟到事件");
297	        }
298	        long readingId = pressureReadingRepository.insert(jobId, request.pressure(),
299	                request.recordedAt(), false, request.requestId());
300	        return new PressureReadingResponse(readingId, true, false, "风压读数已记录");
301	    }
302	
303	    /**
304	     * 查询作业视图。
305	     */
306	    @Transactional(readOnly = true)
307	    public JobResponse getJob(long jobId) {
308	        return toJobResponse(requireJob(jobId));
309	    }
310	
311	    /**
312	     * 复算试验曲线：风压读数（不含迟到数据）与试验事件。
313	     */
314	    @Transactional(readOnly = true)
315	    public TestCurveResponse getTestCurve(long jobId) {
316	        requireJob(jobId);
317	        List<TestCurveResponse.TestPoint> tests = brakeTestRepository.findByJobId(jobId).stream()
318	                .map(t -> new TestCurveResponse.TestPoint(t.testType().name(), t.pressureReduction(),
319	                        t.result().name(), t.consistVersion(), t.voided(), t.createdAt()))
320	                .toList();
321	        return new TestCurveResponse(jobId, pressureReadingRepository.findCurvePoints(jobId), tests);
322	    }
323	
324	    /**
325	     * 复算关门车清单与比例。
326	     */
327	    @Transactional(readOnly = true)
328	    public ClosedCarListResponse getClosedCars(long jobId) {
329	        requireJob(jobId);
330	        List<CarRow> active = carRepository.findActiveByJobId(jobId);
331	        List<String> closedNos = active.stream().filter(CarRow::valveClosed).map(CarRow::carNo).toList();
332	        double ratio = active.isEmpty() ? 0.0 : (double) closedNos.size() / active.size();
333	        return new ClosedCarListResponse(jobId, closedNos, closedNos.size(), active.size(), ratio,
334	                withinClosedCarLimit(closedNos.size(), active.size()));
335	    }
336	
337	    /**
338	     * 复算当前编组版本与在列车辆。
339	     */
340	    @Transactional(readOnly = true)
341	    public ConsistResponse getConsist(long jobId) {
342	        JobRow job = requireJob(jobId);
343	        List<ConsistResponse.CarView> cars = carRepository.findActiveByJobId(jobId).stream()
344	                .map(c -> new ConsistResponse.CarView(c.carNo(), c.seqNo(), c.weightTons(),
345	                        c.length(), c.valveClosed()))
346	                .toList();
347	        return new ConsistResponse(jobId, job.consistVersion(), job.carCount(),
348	                job.totalLength(), job.totalWeight(), cars);
349	    }
350	
351	    private JobRow requireJob(long jobId) {
352	        return jobRepository.findById(jobId)
353	                .orElseThrow(() -> new NotFoundException("作业不存在：" + jobId));
354	    }
355	
356	    private JobRow requireJobForUpdate(long jobId) {
357	        return jobRepository.findByIdForUpdate(jobId)
358	                .orElseThrow(() -> new NotFoundException("作业不存在：" + jobId));
359	    }
360	
361	    private void requireSensitivityPassed(JobRow job) {
362	        requirePassed(job, TestType.SENSITIVITY);
363	    }
364	
365	    private void requirePassed(JobRow job, TestType testType) {
366	        BrakeTestRow latest = brakeTestRepository
367	                .findLatestActive(job.id(), job.consistVersion(), testType)
368	                .orElseThrow(() -> new BusinessException("当前编组版本未完成" + testType + "试验"));
369	        if (latest.result() != TestResult.PASS) {
370	            throw new BusinessException("当前编组版本" + testType + "试验不合格");
371	        }
372	    }
373	
374	    private void checkClosedCarRatio(List<CarDto> cars) {
375	        long closed = cars.stream().filter(CarDto::valveClosed).count();
376	        if (!withinClosedCarLimit(closed, cars.size())) {
377	            throw new BusinessException("关门车比例超过 6%：" + closed + "/" + cars.size());
378	        }
379	    }
380	
381	    private boolean withinClosedCarLimit(long closed, long total) {
382	        return total > 0 && closed * 100 <= total * CLOSED_CAR_LIMIT_PERCENT;
383	    }
384	
385	    private JobResponse toJobResponse(JobRow job) {
386	        List<CarRow> active = carRepository.findActiveByJobId(job.id());
387	        long closed = active.stream().filter(CarRow::valveClosed).count();
388	        double ratio = active.isEmpty() ? 0.0 : (double) closed / active.size();
389	        return new JobResponse(job.id(), job.trainNo(), job.track(), job.status().name(),
390	                job.consistVersion(), job.carCount(), job.totalLength(), job.totalWeight(),
391	                (int) closed, ratio);
392	    }
393	}
