103	        try {
104	            deviceId = deviceRepository.insert(request.deviceNo(), request.selfCheckValidUntil());
105	        } catch (DuplicateKeyException e) {
106	            throw new ConflictException("列尾装置编号已建档：" + request.deviceNo());
107	        }
108	        return toDeviceResponse(deviceRepository.findById(deviceId).orElseThrow());
109	    }
110	
111	    private EotBindingResponse doBind(long jobId, EotBindRequest request) {
112	        // 先锁作业行再条件更新装置行，与摘挂/确认/发车保持统一加锁顺序
113	        JobRow job = requireJobForUpdate(jobId);
114	        EotDeviceRow device = deviceRepository.findByDeviceNo(request.deviceNo())
115	                .orElseThrow(() -> new NotFoundException("列尾装置编号未知：" + request.deviceNo()));
116	        if (request.expectedVersion() != device.version()) {
117	            throw new ConflictException("列尾装置版本冲突：期望 " + request.expectedVersion()
118	                    + "，当前 " + device.version());
119	        }
120	        if (!clock.instant().isBefore(device.selfCheckValidUntil())) {
121	            throw new BusinessException("列尾装置自检不合格或已过有效截止时刻：" + device.selfCheckValidUntil());
122	        }
123	        if (device.boundJobId() != null) {
124	            throw new BusinessException("列尾装置已被作业占用：" + device.boundJobId());
125	        }
126	        if (job.status() == JobStatus.DEPARTURE_CONFIRMED || job.status() == JobStatus.CLOSED) {
127	            throw new BusinessException("当前作业状态不允许绑定列尾装置：" + job.status());
128	        }
129	        if (bindingRepository.findActiveByJobId(jobId).isPresent()) {
130	            throw new BusinessException("作业已绑定列尾装置，不得重复绑定");
131	        }
132	        List<CarRow> activeCars = carRepository.findActiveByJobId(jobId);
133	        if (activeCars.isEmpty()) {
134	            throw new BusinessException("编组为空，无法确定尾车，不得绑定列尾装置");
135	        }
136	        String tailCarNo = activeCars.get(activeCars.size() - 1).carNo();
137	        // 原子条件占用：空闲且版本匹配时生效；并发绑定唯一成功
138	        if (!deviceRepository.occupyIfFree(device.id(), jobId, request.expectedVersion())) {
139	            throw new BusinessException("列尾装置已被占用或版本已变化，绑定失败");
140	        }
141	        long bindingId;
142	        try {
143	            bindingId = bindingRepository.insertActive(device.id(), device.deviceNo(), jobId,
144	                    tailCarNo, job.consistVersion(), request.requestId());
145	        } catch (DuplicateKeyException e) {
146	            // 同作业并发绑定其他装置等场景：唯一约束兜底，事务回滚后占用一并撤销
147	            throw new BusinessException("列尾装置绑定冲突，绑定失败");
148	        }
149	        EotDeviceRow updated = deviceRepository.findById(device.id()).orElseThrow();
150	        return new EotBindingResponse(bindingId, updated.id(), updated.deviceNo(), jobId,
151	                tailCarNo, job.consistVersion(), EotBindingStatus.ACTIVE.name(), updated.version());
152	    }
153	
154	    private EotConfirmationResponse doConfirm(long jobId, EotConfirmRequest request) {
155	        JobRow job = requireJobForUpdate(jobId);
156	        EotBindingRow binding = bindingRepository.findActiveByJobId(jobId)
157	                .orElseThrow(() -> new BusinessException("作业未绑定列尾装置，无法确认一致性"));
158	        if (job.status() == JobStatus.DEPARTURE_CONFIRMED || job.status() == JobStatus.CLOSED) {
159	            throw new BusinessException("当前作业状态不允许列尾一致性确认：" + job.status());
160	        }
161	        EotDeviceRow device = deviceRepository.findById(binding.deviceId()).orElseThrow();
162	        if (request.expectedVersion() != device.version()) {
163	            throw new ConflictException("列尾装置版本冲突：期望 " + request.expectedVersion()
164	                    + "，当前 " + device.version());
165	        }
166	        if (request.confirmer1().equals(request.confirmer2())) {
167	            throw new BusinessException("一致性确认须由两名不同人员共同完成");
168	        }
169	        if (request.consistVersion() != job.consistVersion()) {
170	            throw new BusinessException("确认的编组版本与最新编组不一致：期望 "
171	                    + job.consistVersion() + "，提交 " + request.consistVersion());
172	        }
173	        List<CarRow> activeCars = carRepository.findActiveByJobId(jobId);
174	        if (activeCars.isEmpty()) {
175	            throw new BusinessException("编组为空，无法确定尾车");
176	        }
177	        String currentTailCarNo = activeCars.get(activeCars.size() - 1).carNo();
178	        if (!request.tailCarNo().equals(currentTailCarNo)) {
179	            throw new BusinessException("确认的尾车与当前编组尾车不一致：当前尾车 " + currentTailCarNo);
180	        }
181	        // 乐观版本递增：与摘挂/解绑/并发确认竞争，仅一名成功者提交
182	        if (!deviceRepository.bumpVersionIfBound(device.id(), jobId, request.expectedVersion())) {
183	            throw new ConflictException("列尾装置版本已变化，确认失败");
184	        }
185	        confirmationRepository.invalidateByBindingId(binding.id());
186	        long confirmationId = confirmationRepository.insert(binding.id(), device.id(), device.deviceNo(),
187	                jobId, currentTailCarNo, job.consistVersion(),
188	                request.confirmer1(), request.confirmer2(), request.requestId());
189	        EotDeviceRow updated = deviceRepository.findById(device.id()).orElseThrow();
190	        return new EotConfirmationResponse(confirmationId, binding.id(), device.deviceNo(), jobId,
191	                currentTailCarNo, job.consistVersion(), request.confirmer1(), request.confirmer2(),
192	                true, updated.version());
193	    }
194	
195	    private EotUnbindResponse doUnbind(long jobId, EotUnbindRequest request) {
196	        JobRow job = requireJobForUpdate(jobId);
197	        EotBindingRow binding = bindingRepository.findActiveByJobId(jobId)
198	                .orElseThrow(() -> new BusinessException("作业无生效列尾绑定，无需解绑"));
199	        if (job.status() == JobStatus.DEPARTURE_CONFIRMED || job.status() == JobStatus.CLOSED) {
200	            throw new BusinessException("发车确认后不得提前解绑，列尾装置随销记自动释放：" + job.status());
201	        }
202	        // 释放占用与版本递增原子完成，版本不匹配则整体失败
203	        if (!deviceRepository.releaseIfBoundAndVersion(binding.deviceId(), jobId, request.expectedVersion())) {
204	            EotDeviceRow current = deviceRepository.findById(binding.deviceId()).orElseThrow();
205	            throw new ConflictException("列尾装置版本冲突或占用已变化：期望 " + request.expectedVersion()
206	                    + "，当前 " + current.version());
207	        }
208	        int voided = confirmationRepository.invalidateByBindingId(binding.id());
209	        Instant now = clock.instant();
210	        if (!bindingRepository.release(binding.id(), now)) {
211	            throw new ConflictException("绑定状态已变化，解绑失败");
212	        }
213	        EotDeviceRow updated = deviceRepository.findById(binding.deviceId()).orElseThrow();
214	        return new EotUnbindResponse(binding.id(), updated.id(), updated.deviceNo(), jobId,
215	                true, voided, updated.version());
216	    }
217	
218	    /**
219	     * 摘挂变更同事务联动：绑定保留，但一致性确认立即失效，须重新检查并双人确认。
220	     */
221	    public void invalidateConfirmationsOnConsistChange(long jobId) {
222	        confirmationRepository.invalidateByJobId(jobId);
223	    }
224	
225	    /**
226	     * 销记同事务联动：原子解除装置占用、解除绑定并失效全部确认，绑定历史保留。
227	     */
228	    public void releaseOnClosure(long jobId) {
229	        bindingRepository.findActiveByJobId(jobId).ifPresent(binding -> {
230	            deviceRepository.releaseIfBound(binding.deviceId(), jobId);
231	            confirmationRepository.invalidateByBindingId(binding.id());
232	            bindingRepository.release(binding.id(), clock.instant());
233	        });
234	    }
235	
236	    /**
237	     * 发车确认事务内联动校验（未启用列尾控制的作业直接放行，不增加门禁）：
238	     * 装置自检 UTC 下未过期（恰到截止失效）、存在有效一致性确认且确认的尾车与版本匹配最新编组。
239	     */
240	    public void assertDepartureReady(JobRow job) {
241	        bindingRepository.findActiveByJobId(job.id()).ifPresent(binding -> {
242	            EotDeviceRow device = deviceRepository.findById(binding.deviceId())
243	                    .orElseThrow(() -> new BusinessException("列尾装置档案缺失：" + binding.deviceNo()));
244	            if (device.boundJobId() == null || device.boundJobId() != job.id()) {
245	                throw new BusinessException("列尾装置占用与绑定不一致，拒绝发车");
246	            }
247	            if (!clock.instant().isBefore(device.selfCheckValidUntil())) {
248	                throw new BusinessException("列尾装置自检已过有效截止时刻，拒绝发车："
249	                        + device.selfCheckValidUntil());
250	            }
251	            EotConfirmationRow confirmation = confirmationRepository.findValidByBindingId(binding.id())
252	                    .orElseThrow(() -> new BusinessException("列尾与编组一致性未共同确认，拒绝发车"));
253	            if (confirmation.consistVersion() != job.consistVersion()) {
254	                throw new BusinessException("列尾一致性确认的编组版本已过期，拒绝发车：确认版本 "
255	                        + confirmation.consistVersion() + "，最新版本 " + job.consistVersion());
256	            }
257	            List<CarRow> activeCars = carRepository.findActiveByJobId(job.id());
258	            if (activeCars.isEmpty()) {
259	                throw new BusinessException("编组为空，无法核对列尾尾车");
260	            }
261	            String currentTailCarNo = activeCars.get(activeCars.size() - 1).carNo();
262	            if (!confirmation.tailCarNo().equals(currentTailCarNo)) {
263	                throw new BusinessException("列尾一致性确认的尾车与最新编组尾车不一致，拒绝发车：确认尾车 "
264	                        + confirmation.tailCarNo() + "，当前尾车 " + currentTailCarNo);
265	            }
266	        });
267	    }
268	
269	    /**
270	     * 查询装置完整证据：档案、占用状态与全部绑定历史（含双人确认证据）。
271	     */
272	    public EotDeviceEvidence getDeviceEvidence(String deviceNo) {
273	        EotDeviceRow device = deviceRepository.findByDeviceNo(deviceNo)
274	                .orElseThrow(() -> new NotFoundException("列尾装置编号未知：" + deviceNo));
275	        List<EotBindingRow> bindings = bindingRepository.findAllByDeviceId(device.id());
276	        Map<Long, List<EotConfirmationRow>> confirmations = loadConfirmations(bindings);
277	        List<EotBindingEvidence> bindingEvidences = bindings.stream()
278	                .map(b -> toBindingEvidence(b, confirmations.getOrDefault(b.id(), List.of())))
279	                .toList();
280	        return new EotDeviceEvidence(device.id(), device.deviceNo(), device.selfCheckValidUntil(),
281	                device.boundJobId(), device.version(), bindingEvidences);
282	    }
283	
284	    /**
285	     * 查询作业的列尾绑定与确认证据；未启用列尾控制的作业返回空绑定历史。
286	     */
287	    public List<EotBindingEvidence> getJobEvidence(long jobId) {
288	        requireJob(jobId);
289	        List<EotBindingRow> bindings = bindingRepository.findAllByJobId(jobId);
290	        Map<Long, List<EotConfirmationRow>> confirmations = loadConfirmations(bindings);
291	        return bindings.stream()
292	                .map(b -> toBindingEvidence(b, confirmations.getOrDefault(b.id(), List.of())))
293	                .toList();
294	    }
295	
296	    private Map<Long, List<EotConfirmationRow>> loadConfirmations(List<EotBindingRow> bindings) {
297	        List<Long> bindingIds = bindings.stream().map(EotBindingRow::id).toList();
298	        return confirmationRepository.findAllByBindingIds(bindingIds).stream()
299	                .collect(Collectors.groupingBy(EotConfirmationRow::bindingId));
300	    }
301	
302	    private EotBindingEvidence toBindingEvidence(EotBindingRow binding, List<EotConfirmationRow> rows) {
303	        List<EotConfirmationEvidence> confirmations = new ArrayList<>();
304	        for (EotConfirmationRow row : rows) {
305	            confirmations.add(new EotConfirmationEvidence(row.id(), row.bindingId(), row.deviceNo(),
306	                    row.tailCarNo(), row.consistVersion(), row.confirmer1(), row.confirmer2(),
307	                    row.valid(), row.requestId(), row.createdAt()));
308	        }
309	        return new EotBindingEvidence(binding.id(), binding.deviceId(), binding.deviceNo(),
310	                binding.tailCarNo(), binding.consistVersion(), binding.status().name(),
311	                binding.requestId(), binding.createdAt(), binding.releasedAt(), confirmations);
312	    }
313	
314	    private JobRow requireJob(long jobId) {
315	        return jobRepository.findById(jobId)
316	                .orElseThrow(() -> new NotFoundException("作业不存在：" + jobId));
317	    }
318	
319	    private JobRow requireJobForUpdate(long jobId) {
320	        return jobRepository.findByIdForUpdate(jobId)
321	                .orElseThrow(() -> new NotFoundException("作业不存在：" + jobId));
322	    }
323	
324	    private EotDeviceResponse toDeviceResponse(EotDeviceRow device) {
325	        return new EotDeviceResponse(device.id(), device.deviceNo(), device.selfCheckValidUntil(),
326	                device.boundJobId(), device.version(), device.createdAt());
327	    }
