219	        CountDownLatch start = new CountDownLatch(1);
220	        AtomicInteger success = new AtomicInteger();
221	        AtomicInteger conflict = new AtomicInteger();
222	        List<Future<?>> futures = new ArrayList<>();
223	        for (int i = 0; i < threads; i++) {
224	            int idx = i;
225	            futures.add(pool.submit(() -> {
226	                ready.countDown();
227	                try {
228	                    start.await(5, TimeUnit.SECONDS);
229	                    service.accept(acceptRequest("k9-" + idx, "G10", 10, 0));
230	                    success.incrementAndGet();
231	                } catch (ConflictException e) {
232	                    conflict.incrementAndGet();
233	                } catch (Exception e) {
234	                    throw new RuntimeException(e);
235	                }
236	            }));
237	        }
