43	    /**
44	     * 写入生效绑定（active_device_id/active_job_id 唯一约束兜底并发唯一性）。
45	     */
46	    public long insertActive(long deviceId, String deviceNo, long jobId, String tailCarNo,
47	                             int consistVersion, String requestId) {
48	        KeyHolder keyHolder = new GeneratedKeyHolder();
49	        jdbc.update(con -> {
50	            PreparedStatement ps = con.prepareStatement(
