39	/**
40	 * 途中异常停车与续行许可核心服务（仅模拟软件状态，不控制列车）。
41	 * 登记：仅 DEPARTURE_CONFIRMED 且未销记作业，冻结当前编组、列尾绑定与原发车证据，进入续行阻断，
42	 * 同作业仅一条活动处置；处置期间列尾继续占用，不得销记释放或经旧发车入口绕过。
43	 * 续行：途中试验（复用始发数值/关门车比例/有效时长规则）+ 两名不同人员确认新试验与列尾一致性后，
44	 * 续行入口同事务重查编组、自检有效期及最新试验版本，恰到试验失效点拒绝；任一失败仍停车，不释放装置。
45	 */
46	@Service
47	public class IncidentService {
48	
49	    /** 途中试验有效时长：自试验记录时刻起 6 小时；续行时 UTC 下 now 须早于失效点，恰到即失效。 */
50	    public static final Duration EN_ROUTE_TEST_VALID_DURATION = Duration.ofHours(6);
51	
52	    private final IncidentRepository incidentRepository;
53	    private final EnRouteTestRepository enRouteTestRepository;
54	    private final EnRouteConfirmationRepository enRouteConfirmationRepository;
55	    private final TrainJobRepository jobRepository;
56	    private final TrainCarRepository carRepository;
57	    private final EotBindingRepository bindingRepository;
58	    private final EotDeviceRepository deviceRepository;
59	    private final IdempotencyService idempotencyService;
60	    private final Clock clock;
61	
62	    public IncidentService(IncidentRepository incidentRepository,
63	                           EnRouteTestRepository enRouteTestRepository,
64	                           EnRouteConfirmationRepository enRouteConfirmationRepository,
65	                           TrainJobRepository jobRepository,
66	                           TrainCarRepository carRepository,
67	                           EotBindingRepository bindingRepository,
68	                           EotDeviceRepository deviceRepository,
69	                           IdempotencyService idempotencyService,
70	                           Clock clock) {
71	        this.incidentRepository = incidentRepository;
72	        this.enRouteTestRepository = enRouteTestRepository;
73	        this.enRouteConfirmationRepository = enRouteConfirmationRepository;
74	        this.jobRepository = jobRepository;
75	        this.carRepository = carRepository;
76	        this.bindingRepository = bindingRepository;
77	        this.deviceRepository = deviceRepository;
78	        this.idempotencyService = idempotencyService;
79	        this.clock = clock;
80	    }
81	
82	    /**
83	     * 登记途中异常：冻结当前编组、列尾绑定与原发车证据，进入续行阻断；同作业仅一条活动处置。
84	     */
85	    public IncidentResponse report(long jobId, IncidentReportRequest request) {
86	        return idempotencyService.execute(request.requestId(), "INCIDENT_REPORT",
87	                new IncidentParams(jobId, 0L, request), IncidentResponse.class,
88	                () -> doReport(jobId, request));
89	    }
90	
91	    /**
92	     * 途中制动试验：绑定处置单、当前编组版本与新压力曲线，复用始发试验数值规则；
93	     * 始发曲线不能冒充新试验。
94	     */
95	    public EnRouteTestResponse enRouteTest(long jobId, long incidentId, EnRouteTestRequest request) {
96	        return idempotencyService.execute(request.requestId(), "EN_ROUTE_TEST",
97	                new IncidentParams(jobId, incidentId, request), EnRouteTestResponse.class,
98	                () -> doEnRouteTest(jobId, incidentId, request));
99	    }
100	
101	    /**
102	     * 两名不同人员共同确认途中新试验与列尾一致性；成功后处置版本加 1。
103	     */
104	    public EnRouteConfirmationResponse confirmEnRoute(long jobId, long incidentId,
105	                                                      EnRouteConfirmRequest request) {
106	        return idempotencyService.execute(request.requestId(), "EN_ROUTE_CONFIRM",
107	                new IncidentParams(jobId, incidentId, request), EnRouteConfirmationResponse.class,
108	                () -> doConfirmEnRoute(jobId, incidentId, request));
109	    }
110	
111	    /**
112	     * 续行许可：同事务重查编组、自检有效期及最新试验版本；仅结束本次阻断，证据保留，装置不释放。
113	     */
114	    public ResumeResponse resume(long jobId, long incidentId, ResumeRequest request) {
115	        return idempotencyService.execute(request.requestId(), "RESUME",
116	                new IncidentParams(jobId, incidentId, request), ResumeResponse.class,
117	                () -> doResume(jobId, incidentId, request));
118	    }
119	
120	    private IncidentResponse doReport(long jobId, IncidentReportRequest request) {
121	        JobRow job = requireJobForUpdate(jobId);
122	        if (job.status() != JobStatus.DEPARTURE_CONFIRMED) {
123	            throw new BusinessException("仅发车确认且未销记的作业可登记途中异常：" + job.status());
124	        }
125	        if (incidentRepository.findActiveByJobId(jobId).isPresent()) {
126	            throw new ConflictException("同作业仅一条活动处置，当前处置尚未结束");
127	        }
128	        Long bindingId = bindingRepository.findActiveByJobId(jobId)
129	                .map(EotBindingRow::id).orElse(null);
130	        long incidentId;
131	        try {
132	            incidentId = incidentRepository.insertOpen(jobId, job.consistVersion(), bindingId,
133	                    request.reason(), request.requestId(), clock.instant());
134	        } catch (DuplicateKeyException e) {
135	            // 并发登记：active_job_id 唯一约束兜底，唯一受理
136	            throw new ConflictException("同作业仅一条活动处置，并发登记唯一受理");
137	        }
138	        IncidentRow incident = incidentRepository.findById(incidentId).orElseThrow();
139	        return toResponse(incident, "已登记途中异常，进入续行阻断");
140	    }
141	
142	    private EnRouteTestResponse doEnRouteTest(long jobId, long incidentId, EnRouteTestRequest request) {
143	        JobRow job = requireJobForUpdate(jobId);
144	        IncidentRow incident = requireOpenIncident(jobId, incidentId, job);
145	        requireIncidentVersion(incident, request.expectedVersion());
146	        if (request.pipePressureBefore() < TrainJobService.RATED_PRESSURE_KPA) {
147	            throw new BusinessException("风压未恢复至定压 " + TrainJobService.RATED_PRESSURE_KPA
148	                    + "kPa，不得进行试验");
149	        }
150	        TestResult result;
151	        String message;
152	        if (request.testType() == TestType.SENSITIVITY) {
153	            if (request.pressureReduction() != TrainJobService.SENSITIVITY_REDUCTION_KPA) {
154	                throw new BusinessException("感度试验减压量须为 "
155	                        + TrainJobService.SENSITIVITY_REDUCTION_KPA + "kPa");
156	            }
157	            if (request.allCarsBraked() == null) {
158	                throw new BusinessException("感度试验须上报全列制动情况");
159	            }
160	            result = request.allCarsBraked() ? TestResult.PASS : TestResult.FAIL;
161	            message = result == TestResult.PASS ? "途中感度试验合格" : "途中感度试验不合格：存在未制动车辆";
162	        } else {
163	            requireEnRoutePassed(incident.id(), job.consistVersion(), TestType.SENSITIVITY);
164	            if (request.pressureReduction() != TrainJobService.STABILITY_REDUCTION_KPA) {
165	                throw new BusinessException("安定试验减压量须为 "
166	                        + TrainJobService.STABILITY_REDUCTION_KPA + "kPa");
167	            }
168	            if (request.emergencyOccurred() == null) {
169	                throw new BusinessException("安定试验须上报紧急制动情况");
170	            }
171	            result = request.emergencyOccurred() ? TestResult.FAIL : TestResult.PASS;
172	            message = result == TestResult.PASS ? "途中安定试验合格" : "途中安定试验不合格：发生紧急制动";
173	        }
174	        Instant now = clock.instant();
175	        Instant validUntil = now.plus(EN_ROUTE_TEST_VALID_DURATION);
176	        long testId = enRouteTestRepository.insert(incident.id(), jobId, job.consistVersion(),
177	                request.testType(), request.pressureReduction(), request.pipePressureBefore(),
178	                request.allCarsBraked(), request.emergencyOccurred(), result, validUntil,
179	                request.requestId(), now);
180	        bumpIncidentVersion(incident, request.expectedVersion());
181	        return new EnRouteTestResponse(testId, incident.id(), request.testType().name(), result.name(),
182	                job.consistVersion(), validUntil, request.expectedVersion() + 1, message);
183	    }
184	
185	    private EnRouteConfirmationResponse doConfirmEnRoute(long jobId, long incidentId,
186	                                                         EnRouteConfirmRequest request) {
187	        JobRow job = requireJobForUpdate(jobId);
188	        IncidentRow incident = requireOpenIncident(jobId, incidentId, job);
189	        requireIncidentVersion(incident, request.expectedVersion());
190	        bindingRepository.findActiveByJobId(jobId)
191	                .orElseThrow(() -> new BusinessException("作业未绑定列尾装置，无法确认一致性"));
192	        if (request.confirmer1().equals(request.confirmer2())) {
193	            throw new BusinessException("一致性确认须由两名不同人员共同完成");
194	        }
195	        if (request.consistVersion() != job.consistVersion()) {
196	            throw new BusinessException("确认的编组版本与最新编组不一致：期望 "
197	                    + job.consistVersion() + "，提交 " + request.consistVersion());
198	        }
199	        String currentTailCarNo = currentTailCarNo(jobId);
200	        if (!request.tailCarNo().equals(currentTailCarNo)) {
201	            throw new BusinessException("确认的尾车与当前编组尾车不一致：当前尾车 " + currentTailCarNo);
202	        }
203	        // 确认对象是途中新试验：两项试验须已在当前编组版本下合格
204	        requireEnRoutePassed(incident.id(), job.consistVersion(), TestType.SENSITIVITY);
205	        requireEnRoutePassed(incident.id(), job.consistVersion(), TestType.STABILITY);
206	        enRouteConfirmationRepository.invalidateByIncidentId(incident.id());
207	        long confirmationId = enRouteConfirmationRepository.insert(incident.id(), jobId,
208	                currentTailCarNo, job.consistVersion(), request.confirmer1(), request.confirmer2(),
209	                request.requestId(), clock.instant());
210	        bumpIncidentVersion(incident, request.expectedVersion());
211	        return new EnRouteConfirmationResponse(confirmationId, incident.id(), jobId, currentTailCarNo,
212	                job.consistVersion(), request.confirmer1(), request.confirmer2(), true,
213	                request.expectedVersion() + 1);
214	    }
215	
216	    private ResumeResponse doResume(long jobId, long incidentId, ResumeRequest request) {
217	        JobRow job = requireJobForUpdate(jobId);
218	        if (job.status() == JobStatus.CLOSED) {
219	            throw new BusinessException("作业已销记，不得续行");
220	        }
221	        IncidentRow incident = requireOpenIncident(jobId, incidentId, job);
222	        requireIncidentVersion(incident, request.expectedVersion());
223	        Instant now = clock.instant();
224	        // 同事务重查：最新试验版本匹配当前编组、试验仍在有效时长内（恰到失效点拒绝）
225	        EnRouteTestRow sensitivity = requireEnRoutePassed(incident.id(), job.consistVersion(),
226	                TestType.SENSITIVITY);
227	        EnRouteTestRow stability = requireEnRoutePassed(incident.id(), job.consistVersion(),
228	                TestType.STABILITY);
229	        if (!now.isBefore(sensitivity.validUntil())) {
230	            throw new BusinessException("途中感度试验已过有效截止时刻，仍停车：" + sensitivity.validUntil());
231	        }
232	        if (!now.isBefore(stability.validUntil())) {
233	            throw new BusinessException("途中安定试验已过有效截止时刻，仍停车：" + stability.validUntil());
234	        }
235	        // 关门车比例复用始发规则（恰 6% 合法）
236	        List<CarRow> activeCars = carRepository.findActiveByJobId(jobId);
237	        long closed = activeCars.stream().filter(CarRow::valveClosed).count();
238	        if (activeCars.isEmpty()
239	                || closed * 100 > (long) activeCars.size() * TrainJobService.CLOSED_CAR_LIMIT_PERCENT) {
240	            throw new BusinessException("关门车比例超过 6%，仍停车");
241	        }
242	        // 列尾联动：装置仍被本作业占用、自检未过期（恰到截止失效）、双人确认匹配最新编组与尾车
243	        bindingRepository.findActiveByJobId(jobId).ifPresent(binding -> {
244	            EotDeviceRow device = deviceRepository.findById(binding.deviceId())
245	                    .orElseThrow(() -> new BusinessException("列尾装置档案缺失：" + binding.deviceNo()));
246	            if (device.boundJobId() == null || device.boundJobId() != jobId) {
247	                throw new BusinessException("列尾装置占用与绑定不一致，仍停车");
248	            }
249	            if (!now.isBefore(device.selfCheckValidUntil())) {
250	                throw new BusinessException("列尾装置自检已过有效截止时刻，仍停车："
251	                        + device.selfCheckValidUntil());
252	            }
253	            EnRouteConfirmationRow confirmation = enRouteConfirmationRepository
254	                    .findValidByIncidentId(incident.id())
255	                    .orElseThrow(() -> new BusinessException("途中新试验与列尾一致性未共同确认，仍停车"));
256	            if (confirmation.consistVersion() != job.consistVersion()) {
257	                throw new BusinessException("途中确认的编组版本已过期，仍停车：确认版本 "
258	                        + confirmation.consistVersion() + "，最新版本 " + job.consistVersion());
259	            }
260	            if (!confirmation.tailCarNo().equals(currentTailCarNo(jobId))) {
261	                throw new BusinessException("途中确认的尾车与最新编组尾车不一致，仍停车");
262	            }
263	        });
264	        // 原子续行：仅结束本次阻断；作业仍发车确认态，列尾装置继续占用，证据保留
265	        if (!incidentRepository.resumeIfOpen(incident.id(), request.expectedVersion(), now)) {
266	            throw new ConflictException("处置版本已变化或已续行，续行失败");
267	        }
268	        return new ResumeResponse(incident.id(), jobId, true, request.expectedVersion() + 1,
269	                "准许续行，本次阻断结束，可另报新异常");
270	    }
271	
272	    /**
273	     * 是否存在活动处置（续行阻断中）；发车确认/销记入口据此拒绝绕过。
274	     */
275	    public boolean hasActiveIncident(long jobId) {
276	        return incidentRepository.findActiveByJobId(jobId).isPresent();
277	    }
278	
279	    /**
280	     * 阻断中编组变更同事务联动：待批准途中试验与双人确认立即失效，处置版本加 1，重做后才能续行。
281	     */
282	    public void onConsistChangeDuringBlock(long jobId) {
283	        incidentRepository.findActiveByJobId(jobId).ifPresent(incident -> {
284	            enRouteTestRepository.voidAllByIncidentId(incident.id());
285	            enRouteConfirmationRepository.invalidateByIncidentId(incident.id());
286	            incidentRepository.bumpVersionIfOpen(incident.id(), incident.version());
287	        });
288	    }
289	
290	    /**
291	     * 查询作业全部处置证据（处置单、途中试验与双人确认历史；始发与途中两条证据均保留）。
292	     */
293	    @Transactional(readOnly = true)
294	    public List<IncidentEvidence> getEvidence(long jobId) {
295	        jobRepository.findById(jobId)
296	                .orElseThrow(() -> new NotFoundException("作业不存在：" + jobId));
297	        return incidentRepository.findAllByJobId(jobId).stream()
298	                .map(incident -> new IncidentEvidence(incident.id(), incident.jobId(),
299	                        incident.status().name(), incident.consistVersion(), incident.eotBindingId(),
300	                        incident.version(), incident.reason(), incident.resumedAt(), incident.createdAt(),
301	                        enRouteTestRepository.findByIncidentId(incident.id()).stream()
302	                                .map(t -> new IncidentEvidence.TestPoint(t.id(), t.testType().name(),
303	                                        t.pressureReduction(), t.result().name(), t.consistVersion(),
304	                                        t.voided(), t.validUntil(), t.createdAt()))
305	                                .toList(),
306	                        enRouteConfirmationRepository.findAllByIncidentId(incident.id()).stream()
307	                                .map(c -> new IncidentEvidence.ConfirmationPoint(c.id(), c.tailCarNo(),
308	                                        c.consistVersion(), c.confirmer1(), c.confirmer2(), c.valid(),
309	                                        c.createdAt()))
310	                                .toList()))
311	                .toList();
312	    }
313	
314	    private IncidentRow requireOpenIncident(long jobId, long incidentId, JobRow job) {
315	        if (job.status() != JobStatus.DEPARTURE_CONFIRMED) {
316	            throw new BusinessException("当前作业状态不允许途中处置操作：" + job.status());
317	        }
318	        IncidentRow incident = incidentRepository.findById(incidentId)
319	                .orElseThrow(() -> new NotFoundException("处置单不存在：" + incidentId));
320	        if (incident.jobId() != jobId) {
321	            throw new BusinessException("跨作业引用处置单拒绝：处置单 " + incidentId + " 不属于作业 " + jobId);
322	        }
323	        if (incident.status() != IncidentStatus.OPEN) {
324	            throw new BusinessException("处置已续行结束，不得再操作：" + incidentId);
325	        }
326	        return incident;
327	    }
328	
329	    private void requireIncidentVersion(IncidentRow incident, int expectedVersion) {
330	        if (expectedVersion != incident.version()) {
331	            throw new ConflictException("处置版本冲突：期望 " + expectedVersion
332	                    + "，当前 " + incident.version());
333	        }
334	    }
335	
336	    private void bumpIncidentVersion(IncidentRow incident, int expectedVersion) {
337	        if (!incidentRepository.bumpVersionIfOpen(incident.id(), expectedVersion)) {
338	            throw new ConflictException("处置版本已变化或已续行，操作失败");
339	        }
340	    }
341	
342	    private EnRouteTestRow requireEnRoutePassed(long incidentId, int consistVersion, TestType testType) {
343	        EnRouteTestRow latest = enRouteTestRepository
344	                .findLatestActive(incidentId, consistVersion, testType)
345	                .orElseThrow(() -> new BusinessException("当前编组版本未完成途中" + testType + "试验"));
346	        if (latest.result() != TestResult.PASS) {
347	            throw new BusinessException("当前编组版本途中" + testType + "试验不合格");
348	        }
349	        return latest;
350	    }
351	
352	    private String currentTailCarNo(long jobId) {
353	        List<CarRow> activeCars = carRepository.findActiveByJobId(jobId);
354	        if (activeCars.isEmpty()) {
355	            throw new BusinessException("编组为空，无法确定尾车");
356	        }
357	        return activeCars.get(activeCars.size() - 1).carNo();
358	    }
359	
360	    private JobRow requireJobForUpdate(long jobId) {
361	        return jobRepository.findByIdForUpdate(jobId)
362	                .orElseThrow(() -> new NotFoundException("作业不存在：" + jobId));
363	    }
364	
365	    private IncidentResponse toResponse(IncidentRow incident, String message) {
366	        return new IncidentResponse(incident.id(), incident.jobId(), incident.status().name(),
367	                incident.consistVersion(), incident.eotBindingId(), incident.version(),
368	                incident.reason(), incident.resumedAt(), incident.createdAt(), message);
369	    }
370	
371	    /** 途中处置幂等指纹参数：路径作业ID、处置单ID与请求体共同结构化参与指纹。 */
372	    private record IncidentParams(long jobId, long incidentId, Object request) {
373	    }
374	}
